        &lt;/thead&gt;

        &lt;tbody&gt;
            @forelse($details as $item)
                &lt;tr&gt;
                    &lt;td&gt;{{ $item['invoice']['number'] ?? '-' }}&lt;/td&gt;
                    &lt;td&gt;{{ $item['product_name'] ?? '-' }}&lt;/td&gt;
                    &lt;td&gt;{{ $item['unit_price'] ?? '-' }}&lt;/td&gt;
