                    &lt;td&gt;{{ $item['line_total'] ?? '-' }}&lt;/td&gt;
                &lt;/tr&gt;
            @empty
                &lt;tr&gt;
                    &lt;td colspan=&quot;5&quot; class=&quot;text-center&quot;&gt;Nincs megjeleníthető tétel.&lt;/td&gt;
                &lt;/tr&gt;
            @endforelse
        &lt;/tbody&gt;

    &lt;/table&gt;

&lt;/div&gt;

@endsection
</code></pre>
<p>And finally the web.php:</p>
<pre><code>&lt;?php

use Illuminate\Support\Facades\Route;
use App\Http\Controllers\PageController;

Route::get('/', function () {
    return view('home');
})-&gt;name('home');

Route::get('/list', [PageController::class, 'list'])-&gt;name('list');
Route::get('/search', [PageController::class, 'search'])-&gt;name('search');

Route::delete('/invoice/delete/{id}', [PageController::class, 'deleteInvoice'])
    -&gt;name('invoice.delete');

Route::get('/invoices', function () {
    return view('search');
})-&gt;name('invoices.index');

Route::get('/invoice-details', function () {
    return view('list');
})-&gt;name('invoice_details.index');
</code></pre>

Q: I want to take (B → (C → B)), and turn it into (&#172;(C) → (B → &#172;(C))) using the mapping {B=&#172;(C), C=B} A: <p>Other method is to send all replacements as list</p>
<pre><code>rules = [(b, Not(c)), (c, b)]
prop = prop.subs(rules)
</code></pre>
<p>and use <code>for</code>-loop to change them</p>
<pre><code>def subs(self, rules):  # this is the incorrect solution I currently have
    for target, replacement in rules:
        if self == target:
            return replacement
    return self
</code></pre>
<p>It needs to use list in every <code>subs</code></p>
<pre class="lang-py prettyprint-override"><code>from dataclasses import dataclass, field


@dataclass(frozen=True)
class Symb:
    pass


@dataclass(frozen=True)
class PrimConn(Symb):
    pass


@dataclass(frozen=True)
class Not(PrimConn):
    arg: Symb

    def __repr__(self):
        return f&quot;¬({self.arg})&quot;

    # def subs(self, mapping: dict): This is the goal
    #     pass
    def subs(self, rules):  # this is the incorrect solution I currently have
        return Not(self.arg.subs(rules))


@dataclass(frozen=True)
class To(PrimConn):
    arg1: Symb
    arg2: Symb

    def __repr__(self):
        return f&quot;({self.arg1} → {self.arg2})&quot;

    # def subs(self, mapping: dict): This is the goal
    #     pass
    def subs(self, rules):  # this is the incorrect solution I currently have
        return To(self.arg1.subs(rules), self.arg2.subs(rules))


@dataclass(frozen=True)
class StatLett(Symb):
    name: str

    def __repr__(self):
        return self.name

    def subs(self, rules):  # this is the incorrect solution I currently have
        for target, replacement in rules:
            if self == target:
                return replacement
        return self


def main():

    b = StatLett(&quot;B&quot;)
    c = StatLett(&quot;C&quot;)

    prop = To(b, To(c, b))
    print(prop)  # prints (B → (C → B))

    rules = [(b, Not(c)), (c, b)]
    prop = prop.subs(rules)
    print(prop)


if __name__ == &quot;__main__&quot;:
    main()
</code></pre>
<p>But you may have to check if it works in every situation.</p>
